using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Existing 500K documents use "Discriminator", so we must keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityName|Key" to just the key value.
            // Existing documents have id = "Product|123". Opt in to the legacy format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

            // EF Core 9 breaking change #3: Sync I/O now throws by default.
            // See CosmosQuery.cs — we switched to async. If sync is still needed:
            // options.AllowSynchronousQueryExecution = true; in OnConfiguring.

            entity.HasIndex(p => p.Sku);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

